<?php
$active_menu='clients';include 'header.php';require_once __DIR__.'/../foundation.php';oecrm_require_permission($conn,'clients','view');$companyId=oecrm_current_company_id($conn);$status=trim($_GET['status']??'');$q=trim($_GET['q']??'');$where='c.company_id=?';$types='i';$params=[$companyId];if(in_array($status,['prospect','active','inactive','on_hold','closed'],true)){$where.=' AND c.status=?';$types.='s';$params[]=$status;}if($q!==''){$where.=' AND (c.display_name LIKE ? OR c.client_code LIKE ? OR c.email LIKE ?)';$like='%'.$q.'%';$types.='sss';array_push($params,$like,$like,$like);}$sql='SELECT c.*,(SELECT COUNT(*) FROM client_contacts x WHERE x.client_id=c.id AND x.status=1) contact_count,(SELECT COUNT(*) FROM client_contracts x WHERE x.client_id=c.id AND x.status="active") contract_count,(SELECT COUNT(*) FROM projectstbl p WHERE p.client_id=c.id) project_count,(SELECT MAX(communication_at) FROM client_communications x WHERE x.client_id=c.id) last_contact FROM clients c WHERE '.$where.' ORDER BY FIELD(c.status,"active","prospect","on_hold","inactive","closed"),c.display_name';$s=mysqli_prepare($conn,$sql);mysqli_stmt_bind_param($s,$types,...$params);mysqli_stmt_execute($s);$clients=mysqli_stmt_get_result($s);$stats=mysqli_fetch_assoc(mysqli_query($conn,'SELECT COUNT(*) total,SUM(status="active") active,SUM(status="prospect") prospects,SUM(status="on_hold") on_hold FROM clients WHERE company_id='.(int)$companyId));$flash=$_SESSION['client_flash']??'';unset($_SESSION['client_flash']);
?><div id="page-wrapper" class="compact-admin-page client-page"><?php if($flash):?><div class="alert alert-success"><?php echo oecrm_h($flash);?></div><?php endif;?><div class="client-summary"><div><i class="fa fa-address-book"></i><span><small>Total Clients</small><strong><?php echo (int)$stats['total'];?></strong></span></div><div><i class="fa fa-check-circle"></i><span><small>Active</small><strong><?php echo (int)$stats['active'];?></strong></span></div><div><i class="fa fa-user-plus"></i><span><small>Prospects</small><strong><?php echo (int)$stats['prospects'];?></strong></span></div><div><i class="fa fa-pause-circle"></i><span><small>On Hold</small><strong><?php echo (int)$stats['on_hold'];?></strong></span></div></div><div class="panel panel-default"><div class="panel-heading foundation-heading"><span>Client Directory</span><a class="btn btn-primary btn-sm" href="clientProfile.php"><i class="fa fa-plus"></i> Add Client</a></div><div class="panel-body"><form method="get" class="client-filters"><input class="form-control" name="q" value="<?php echo oecrm_h($q);?>" placeholder="Search client, code or email"><select class="form-control" name="status"><option value="">All statuses</option><?php foreach(['active','prospect','on_hold','inactive','closed'] as $v):?><option value="<?php echo $v;?>" <?php echo $status===$v?'selected':'';?>><?php echo ucwords(str_replace('_',' ',$v));?></option><?php endforeach;?></select><button class="btn btn-default"><i class="fa fa-search"></i> Search</button></form><div class="table-responsive"><table class="table foundation-table"><thead><tr><th>Client</th><th>Contact</th><th>Status</th><th>Projects</th><th>Contracts</th><th>Last Contact</th><th>Actions</th></tr></thead><tbody><?php if(mysqli_num_rows($clients)===0):?><tr><td colspan="7" class="empty-cell">No clients found.</td></tr><?php endif;?><?php while($c=mysqli_fetch_assoc($clients)):?><tr><td><strong><?php echo oecrm_h($c['display_name']);?></strong><small><?php echo oecrm_h($c['client_code'].' | '.($c['industry']?:ucfirst($c['client_type'])));?></small></td><td><?php echo oecrm_h($c['email']?:'-');?><small><?php echo oecrm_h($c['phone']);?></small></td><td><span class="client-status <?php echo $c['status'];?>"><?php echo ucwords(str_replace('_',' ',$c['status']));?></span></td><td><?php echo (int)$c['project_count'];?></td><td><?php echo (int)$c['contract_count'];?></td><td><?php echo $c['last_contact']?date('d M Y',strtotime($c['last_contact'])):'Never';?></td><td><a class="icon-action" href="clientProfile.php?id=<?php echo (int)$c['id'];?>" title="Open Client"><i class="fa fa-eye"></i></a><?php if(!in_array($c['status'],['inactive','closed'],true)&&oecrm_can($conn,'clients','delete')):?><form method="post" action="clientAction.php" style="display:inline" data-confirm="Archive this client? Active projects will place the client on hold."><?php echo oecrm_csrf_field();?><input type="hidden" name="action" value="archive_client"><input type="hidden" name="client_id" value="<?php echo (int)$c['id'];?>"><button class="icon-action danger" title="Archive"><i class="fa fa-archive"></i></button></form><?php endif;?></td></tr><?php endwhile;?></tbody></table></div></div></div></div><?php include 'footer.php';?>
